import { CustomBlobDocument, Microflows, StudioProApi } from "@mendix/extensions-api";
import { CommonModelEntities } from "../constants/genAICommonsEntities";
import { ToolTypes } from "../constants/mcp";
import { Agent } from "../types/agent";
import { Tool, ToolType } from "../types/tool";
import { getCustomBlobDocumentById } from "./customBlobDocumentUtils";
import { getMicroflowById } from "./microflowUtils";

export function createNewTool(name?: string): Tool {
    return {
        id: crypto.randomUUID(),
        name: name ? name : "",
        description: "",
        enabled: true,
        toolType: "" as ToolType,
        document: {
            documentId: "",
            qualifiedName: "",
        },
    };
}

export const validateMCPTool = async (tool: Tool, studioPro: StudioProApi, agent: Agent): Promise<true | string> => {
    if (tool.toolType !== ToolTypes.MCP) {
        throw new Error("validateMCPTool can only be used to validate tools of type MCP.");
    }

    const existingTools: Tool[] = agent.tools;

    if (!tool.document || !tool.document.documentId) {
        return "Consumed MCP service must be selected for MCP tool.";
    }
    const document = await getCustomBlobDocumentById(studioPro, tool.document.documentId);
    if (!document) {
        return "Consumed MCP service document does not exist.";
    }
    if (document.excluded === true) {
        return "Selected Consumed MCP service is currently excluded from the project and cannot be used.";
    }
    if (
        existingTools &&
        existingTools.some(
            (t) =>
                t.toolType === ToolTypes.MCP && t.document.documentId === tool.document?.documentId && t.id !== tool.id
        )
    ) {
        return "Consumed MCP service must be unique among tools.";
    }

    return true;
};

export const validateMicroflowTool = async (tool: Tool, studioPro: StudioProApi): Promise<true | string> => {
    if (tool.toolType !== ToolTypes.Microflow) {
        throw new Error("validateMicroflowTool can only be used to validate tools of type Microflow.");
    }

    if (!tool.document || !tool.document.documentId) {
        return "Microflow must be selected for Microflow tool.";
    }

    const microflow: Microflows.Microflow | null = await getMicroflowById(studioPro, tool.document.documentId);

    if (microflow === null) {
        return "Selected microflow does not exist.";
    }
    if (microflow.excluded === true) {
        return "Selected microflow is currently excluded from the project and cannot be used.";
    }
    if (microflow.microflowReturnType.$Type !== "DataTypes$StringType") {
        return "Tool microflow must return a String.";
    }
    const validateParameterTypesResult = validateMicroflowParameterTypes(microflow);

    if (validateParameterTypesResult) {
        return validateParameterTypesResult;
    }

    return true;
};

export const validateMicroflowParameterTypes = (microflow: Microflows.Microflow): string | undefined => {
    const allowedObjectEntities = [CommonModelEntities.Request, CommonModelEntities.Tool];
    const allowedMicroflowParameterTypes = [
        "DataTypes$StringType",
        "DataTypes$BooleanType",
        "DataTypes$IntegerType",
        "DataTypes$DecimalType",
        "DataTypes$FloatType",
        "DataTypes$DateTimeType",
        "DataTypes$VoidType",
        "DataTypes$EmptyType",
        "DataTypes$EnumerationType",
    ];

    const microflowObjects: Microflows.MicroflowObject[] | undefined = microflow.objectCollection.objects;

    if (microflowObjects) {
        for (const param of microflowObjects) {
            if (param.$Type === "Microflows$MicroflowParameterObject") {
                if (allowedMicroflowParameterTypes.includes(param.variableType.$Type)) {
                    continue;
                } else if (
                    param.variableType.$Type === "DataTypes$ObjectType" &&
                    allowedObjectEntities.includes(param.variableType.entity)
                ) {
                    continue;
                } else {
                    return `Tool microflow parameter "${param.name}" has an unsupported type. Only primitive types and GenAICommons.Request or GenAICommons.Tool objects are allowed.`;
                }
            }
        }
    }

    return undefined;
};

/**
 * Retrieves a tool document by its document ID and type.
 * For MCP tools it looks up a custom blob document; for Microflow tools it looks up a microflow.
 * @param studioPro - The StudioPro API instance.
 * @param toolType - The type of the tool to look up.
 * @param documentId - The document ID of the tool document.
 * @returns The matching tool document, or `undefined` if it cannot be found or the type is unrecognised.
 */
export const getToolById = async (
    studioPro: StudioProApi,
    toolType: ToolType,
    documentId: string
): Promise<Microflows.Microflow | CustomBlobDocument | undefined> => {
    let tool: Microflows.Microflow | CustomBlobDocument | undefined;

    if (toolType === ToolTypes.MCP) {
        tool = await getCustomBlobDocumentById(studioPro, documentId);
    } else if (toolType === ToolTypes.Microflow) {
        tool = (await getMicroflowById(studioPro, documentId)) || undefined;
    }

    return tool;
};

/**
 * Returns a human-readable label for a given tool type.
 * @param toolType - The type of the tool.
 * @returns A display label string (e.g. "Microflow", "Consumed MCP service").
 */
export const getToolLabel = (toolType: ToolType): string => {
    switch (toolType) {
        case ToolTypes.Microflow:
            return "Microflow";
        case ToolTypes.MCP:
            return "Consumed MCP service";
        default:
            return "Tool";
    }
};

/**
 * Type guard that determines whether a tool document is a microflow.
 * Microflow objects expose `microflowActionInfo`, whereas custom blob documents expose `contents`.
 * @param tool - The tool document to check.
 * @returns `true` if the tool is a `Microflows.Microflow`, `false` otherwise.
 */
export const isMicroflowTool = (tool: Microflows.Microflow | CustomBlobDocument): tool is Microflows.Microflow => {
    return "microflowActionInfo" in tool;
};

/**
 * Type guard that determines whether a tool document is a custom blob document.
 * Custom blob documents expose `contents`, whereas microflow objects expose `microflowActionInfo`.
 * @param tool - The tool document to check.
 * @returns `true` if the tool is an `CustomBlobDocument`, `false` otherwise.
 */
export const isMCPTool = (tool: Microflows.Microflow | CustomBlobDocument): tool is CustomBlobDocument => {
    return "contents" in tool;
};
