import { ComponentContext, getStudioProApi, IComponent } from "@mendix/extensions-api";
import { createStudioProLogger } from "../config/logger";
import { agentIconBase64 } from "../icons/agentIcons";
import { mendixCloudGenAIIconBase64 } from "../icons/modelIcons";
import { mcpIconBase64 } from "../icons/toolIcons";
import { registerAgentConsistencyChecks } from "../ui/agent/agentConsistencyChecks";
import { registerConsumedMCPConsistencyChecks } from "../ui/consumedMCPService/consumedMCPConsistencyChecks";
import { registerModelConsistencyChecks } from "../ui/model/modelConsistencyChecks";
import { createNewAgent } from "../utils/agentUtils";
import { createNewConsumedMCPService } from "../utils/consumedMCPServiceUtils";
import { createNewModel } from "../utils/modelUtils";

export const componentName = "extension/agent-editor";

export const agentDocumentTypeId = "agenteditor.agent";
export const modelDocumentTypeId = "agenteditor.model";
export const consumedMCPServiceDocumentTypeId = "agenteditor.consumedMCPService";
//const knowledgebaseDocumentTypeId = "agenteditor.knowledgebase";

class Main implements IComponent {
    async loaded(componentContext: ComponentContext) {
        const studioPro = getStudioProApi(componentContext);
        const logger = createStudioProLogger(studioPro);

        try {
            await studioPro.app.model.customBlobDocuments.registerDocumentType({
                type: agentDocumentTypeId,
                readableTypeName: "Agent",
                defaultContent: createNewAgent(),
                consistencyCheckRegistration: registerAgentConsistencyChecks(studioPro),
            });

            await studioPro.ui.editors.registerEditorForCustomDocument({
                documentType: agentDocumentTypeId,
                editorKind: "tab",
                editorEntryPoint: "agentEdit",
                iconLight: agentIconBase64,
                iconDark: agentIconBase64,
            });

            await studioPro.app.model.customBlobDocuments.registerDocumentType({
                type: modelDocumentTypeId,
                readableTypeName: "Model",
                defaultContent: createNewModel(),
                consistencyCheckRegistration: registerModelConsistencyChecks(studioPro),
            });

            await studioPro.ui.editors.registerEditorForCustomDocument({
                documentType: modelDocumentTypeId,
                editorKind: "tab",
                editorEntryPoint: "modelEdit",
                iconLight: mendixCloudGenAIIconBase64,
                iconDark: mendixCloudGenAIIconBase64,
            });

            await studioPro.app.model.customBlobDocuments.registerDocumentType({
                type: consumedMCPServiceDocumentTypeId,
                readableTypeName: "Consumed MCP service",
                defaultContent: createNewConsumedMCPService(),
                consistencyCheckRegistration: registerConsumedMCPConsistencyChecks(studioPro),
            });

            await studioPro.ui.editors.registerEditorForCustomDocument({
                documentType: consumedMCPServiceDocumentTypeId,
                editorKind: "tab",
                editorEntryPoint: "consumedMCPServiceEdit",
                iconLight: mcpIconBase64,
                iconDark: mcpIconBase64,
            });

            /*

            await studioPro.app.model.customBlobDocuments.registerDocumentType({
                type: knowledgebaseDocumentTypeId,
                readableTypeName: "Knowledge base",
                defaultContent: createNewKnowledgebase()
            });

            await studioPro.ui.editors.registerEditorForCustomDocument({
                documentType: knowledgebaseDocumentTypeId,
                editorKind: "tab",
                editorEntryPoint: "knowledgebaseEdit",
                iconLight: knowledgebaseIconBase64,
                iconDark: knowledgebaseIconBase64
            });
*/
        } catch (error) {
            logger.error("Error during extension initialization:", error);
            await studioPro.ui.messageBoxes.show(
                "error",
                `Error during extension initialization: ${(error as Error).message}`
            );
            throw error;
        }
    }
}

export const component: IComponent = new Main();
