import { ConsistencyError, StudioProApi } from "@mendix/extensions-api";
import {
    KEY_EXCLUDED_ERROR_CODE,
    KEY_INVALID_TYPE_ERROR_CODE,
    KEY_NOT_FOUND_ERROR_CODE,
    KEY_REQUIRED_ERROR_CODE,
    MODEL_RESERVED_ERROR_CODES,
} from "../../constants/consistencyCodes";
import { ConsistencyCheckResult } from "../../types/generic";
import { Model } from "../../types/model/model";
import { MxCloudGenAIModelFields } from "../../types/model/mxCloudGenAIModel";
import { getConstantById, isStringConstant } from "../../utils/constantUtils";

export const registerModelConsistencyChecks = (studioPro: StudioProApi) => ({
    check: async (document: Model) => {
        const keyResult = await checkKey(studioPro, document);

        return {
            errors: [...keyResult.errors],
            dependentElementIds: [...keyResult.dependentElementIds],
        };
    },
    reservedErrorCodes: MODEL_RESERVED_ERROR_CODES,
});

async function checkKey(studioPro: StudioProApi, document: Model): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    const providerFields = document.providerFields as MxCloudGenAIModelFields;

    if (!providerFields.key) {
        errors.push({
            errorCode: KEY_REQUIRED_ERROR_CODE,
            errorDescription: "Key is required for a Mendix Cloud model.",
            severity: "error",
            elementText: "Model key",
        });
        return { errors, dependentElementIds };
    }

    dependentElementIds.push(providerFields.key.documentId);

    const constant = await getConstantById(studioPro, providerFields.key.documentId);

    if (!constant) {
        errors.push({
            errorCode: KEY_NOT_FOUND_ERROR_CODE,
            errorDescription: `The constant ${providerFields.key.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
            severity: "error",
            elementText: "Model key",
        });
    } else if (constant.excluded) {
        errors.push({
            errorCode: KEY_EXCLUDED_ERROR_CODE,
            errorDescription: `The constant ${providerFields.key.qualifiedName} is excluded from the project and cannot be used.`,
            severity: "error",
            elementText: "Model key",
        });
    } else if (!isStringConstant(constant)) {
        errors.push({
            errorCode: KEY_INVALID_TYPE_ERROR_CODE,
            errorDescription: `The constant ${providerFields.key.qualifiedName} must be of type string.`,
            severity: "error",
            elementText: "Model key",
        });
    }

    return { errors, dependentElementIds };
}
