import { StudioProApi } from "@mendix/extensions-api";
import { createStudioProLogger } from "../config/logger";
import { DEFAULT_MCP_PROTOCOL_VERSION } from "../constants/mcp";
import { ConsumedMCPService } from "../types/consumedMCPService";

export function createNewConsumedMCPService(): ConsumedMCPService {
    return {
        protocolVersion: DEFAULT_MCP_PROTOCOL_VERSION,
    };
}

export const updateConsumedMCPServiceDocument =
    (studioPro: StudioProApi, documentId: string) => async (consumedMCPService: ConsumedMCPService) => {
        const logger = createStudioProLogger(studioPro);
        try {
            await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, consumedMCPService);
        } catch (error) {
            logger.error("Failed to save consumed MCP service document:", error);
            await studioPro.ui.notifications.show({
                title: "Failed to save consumed MCP service document.",
                message: (error as Error).message,
            });
        }
    };
