import { ConsistencyError, Microflows, StudioProApi } from "@mendix/extensions-api";
import {
    AUTH_MICROFLOW_EXCLUDED_ERROR_CODE,
    AUTH_MICROFLOW_INVALID_INPUT_PARAMS_ERROR_CODE,
    AUTH_MICROFLOW_INVALID_RETURN_TYPE_ERROR_CODE,
    AUTH_MICROFLOW_NOT_FOUND_ERROR_CODE,
    CONSUMED_MCP_RESERVED_ERROR_CODES,
    ENDPOINT_EXCLUDED_ERROR_CODE,
    ENDPOINT_INVALID_TYPE_ERROR_CODE,
    ENDPOINT_NOT_FOUND_ERROR_CODE,
    ENDPOINT_REQUIRED_ERROR_CODE,
} from "../../constants/consistencyCodes";
import { CommonModelEntities } from "../../constants/genAICommonsEntities";
import { ConsumedMCPService } from "../../types/consumedMCPService";
import { ConsistencyCheckResult } from "../../types/generic";
import { getConstantById, isStringConstant } from "../../utils/constantUtils";
import { getMicroflowById } from "../../utils/microflowUtils";

export const registerConsumedMCPConsistencyChecks = (studioPro: StudioProApi) => ({
    check: async (document: ConsumedMCPService) => {
        const endpointResult = await checkEndpoint(studioPro, document);
        const authMicroflowResult = await checkAuthenticationMicroflow(studioPro, document);

        return {
            errors: [...endpointResult.errors, ...authMicroflowResult.errors],
            dependentElementIds: [...endpointResult.dependentElementIds, ...authMicroflowResult.dependentElementIds],
        };
    },
    reservedErrorCodes: CONSUMED_MCP_RESERVED_ERROR_CODES,
});

async function checkEndpoint(studioPro: StudioProApi, document: ConsumedMCPService): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    if (!document.endpoint) {
        errors.push({
            errorCode: ENDPOINT_REQUIRED_ERROR_CODE,
            errorDescription: "Endpoint is required for a consumed MCP service.",
            severity: "error",
            elementText: "Endpoint",
        });
        return { errors, dependentElementIds };
    }

    dependentElementIds.push(document.endpoint.documentId);

    const constant = await getConstantById(studioPro, document.endpoint.documentId);

    if (!constant) {
        errors.push({
            errorCode: ENDPOINT_NOT_FOUND_ERROR_CODE,
            errorDescription: `The constant ${document.endpoint.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
            severity: "error",
            elementText: "Endpoint",
        });
    } else if (constant.excluded) {
        errors.push({
            errorCode: ENDPOINT_EXCLUDED_ERROR_CODE,
            errorDescription: `The constant ${document.endpoint.qualifiedName} is excluded from the project and cannot be used.`,
            severity: "error",
            elementText: "Endpoint",
        });
    } else if (!isStringConstant(constant)) {
        errors.push({
            errorCode: ENDPOINT_INVALID_TYPE_ERROR_CODE,
            errorDescription: `The constant ${document.endpoint.qualifiedName} must be of type string.`,
            severity: "error",
            elementText: "Endpoint",
        });
    }

    return { errors, dependentElementIds };
}

async function checkAuthenticationMicroflow(
    studioPro: StudioProApi,
    document: ConsumedMCPService
): Promise<ConsistencyCheckResult> {
    const errors: ConsistencyError[] = [];
    const dependentElementIds: string[] = [];

    if (!document.authenticationMicroflow) {
        return { errors, dependentElementIds };
    }

    dependentElementIds.push(document.authenticationMicroflow.documentId);

    const microflow: Microflows.Microflow | null = await getMicroflowById(
        studioPro,
        document.authenticationMicroflow.documentId
    );

    if (!microflow) {
        errors.push({
            errorCode: AUTH_MICROFLOW_NOT_FOUND_ERROR_CODE,
            errorDescription: `Microflow ${document.authenticationMicroflow.qualifiedName} could not be found. Please make sure it exists and is correctly referenced.`,
            severity: "error",
            elementText: "Authentication microflow",
        });

        return { errors, dependentElementIds };
    }

    if (microflow.excluded) {
        errors.push({
            errorCode: AUTH_MICROFLOW_EXCLUDED_ERROR_CODE,
            errorDescription: `Microflow ${document.authenticationMicroflow.qualifiedName} is excluded from the project and cannot be used.`,
            severity: "error",
            elementText: "Authentication microflow",
        });

        return { errors, dependentElementIds };
    }

    if (
        microflow.objectCollection.objects?.filter((obj) => obj.$Type === "Microflows$MicroflowParameterObject")
            .length !== 0
    ) {
        errors.push({
            errorCode: AUTH_MICROFLOW_INVALID_INPUT_PARAMS_ERROR_CODE,
            errorDescription: `Microflow ${document.authenticationMicroflow.qualifiedName} cannot have input parameters.`,
            severity: "error",
            elementText: "Authentication microflow",
        });
    }

    if (
        microflow.microflowReturnType.$Type !== "DataTypes$ListType" ||
        microflow.microflowReturnType.entity !== CommonModelEntities.HttpHeader
    ) {
        errors.push({
            errorCode: AUTH_MICROFLOW_INVALID_RETURN_TYPE_ERROR_CODE,
            errorDescription: `Microflow ${document.authenticationMicroflow.qualifiedName} must return a list of System.HttpHeader objects.`,
            severity: "error",
            elementText: "Authentication microflow",
        });
    }

    return { errors, dependentElementIds };
}
